"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View3 from "./components/footer-sections/variants/04-studio";
const variants = {"studio":View3};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "studio"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "studio", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link, and where it goes. Links to other sites (http or https) open in a new tab. */
export interface ArtemisFooterLink {
  label: string;
  href: string;
}

/** A link in a column. */
export interface ArtemisFooterColumnLink extends ArtemisFooterLink {
  /** Shows the link in the stronger style, for a "browse all" link. landscape. */
  highlight?: boolean;
}

/** A small heading over a list of links. */
export interface ArtemisFooterColumn {
  title: string;
  links: ArtemisFooterColumnLink[];
}

/** A profile or contact link drawn as an icon. Its label names the link for screen readers, and is its tooltip where the layout has one. */
export interface ArtemisFooterSocialLink extends ArtemisFooterLink {
  /** The icon. Without one, the link keeps the icon the layout draws in that position. */
  icon?: ComponentType<{ className?: string }>;
}

/** A picture, and the words that describe it. */
export interface ArtemisFooterImage {
  src: string;
  alt: string;
}

/** An email sign-up form. */
export interface ArtemisFooterNewsletter {
  /** The heading over the form. */
  title: string;
  /** A line under the heading. */
  text: string;
  /** Sample text in the empty email field. */
  placeholder: string;
  /** The button. */
  button: string;
  /** The button while the address is being sent. */
  sending: string;
  /** The button once the address is sent. */
  sent: string;
}

/** A live clock for one city. */
export interface ArtemisFooterClock {
  /** The city named beside the clock face. */
  city: string;
  /** The city's IANA time zone, such as "Europe/Copenhagen". The clock stays blank if the zone is unknown. */
  timeZone: string;
  /** A line over the time. */
  caption: string;
}

/** The words on an Artemis footer. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFooterContent {
  /** The name beside the logo mark, and where it links. All layouts; wordmark, spotlight and mega show the name without a link, and wordmark and spotlight also draw it large across the foot. */
  brand: ArtemisFooterLink;
  /** A sentence about the brand. landscape, studio, local-time, frame, spotlight, mega and cta. */
  tagline?: string;
  /** The footer's main line. panorama and wordmark show it as a heading, landscape as a line under `tagline`, studio as a line over `cta`. */
  headline?: string;
  /** The styled end of the headline. It goes with `headline`: give `headline` alone and it shows alone, give both and both show. panorama, wordmark and landscape style it; studio runs it on after `headline`. */
  headlineAccent?: string;
  /** A paragraph under the headline. panorama. */
  subhead?: string;
  /** The main link. panorama and wordmark show it as a button, studio as a large underlined link. */
  cta?: ArtemisFooterLink;
  /** A quieter button beside `cta`. panorama. */
  secondaryCta?: ArtemisFooterLink;
  /** A short status, such as availability. studio and mega show it in a pill with a dot. */
  status?: string;
  /** A picture. panorama shows it wide; studio shows it over `location`. */
  image?: ArtemisFooterImage;
  /** Where you are, beside a map pin. studio. */
  location?: string;
  /** A row of links without headings. panorama and studio, which list the links of `columns` instead when you give only those. */
  links?: ArtemisFooterLink[];
  /** Columns of links under small headings. wordmark, landscape, local-time, frame, spotlight, mega and cta. */
  columns?: ArtemisFooterColumn[];
  /** An email sign-up form. mega. */
  newsletter?: ArtemisFooterNewsletter;
  /** A live clock for one city. local-time. */
  clock?: ArtemisFooterClock;
  /** Icon links to profiles or email. panorama, landscape, studio, frame, mega and cta. */
  social?: ArtemisFooterSocialLink[];
  /** The copyright line. All layouts but landscape. */
  legal?: string;
  /** Small links beside the copyright line. panorama, studio, local-time, frame and cta. */
  legalLinks?: ArtemisFooterLink[];
  /** A short closing line near the copyright. wordmark, frame and spotlight. */
  note?: string;
}

"use client";
// @zeus-internal
import { MotionConfig, motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisFooterContent, ArtemisFooterSocialLink } from "../content";
const TEXT_HIDDEN = { opacity: 0, y: 12 } as const;
const IMAGE_HIDDEN = { opacity: 0, scale: 1.04 } as const;
const TEXT_SHOWN = { opacity: 1, y: 0 } as const;
const IMAGE_SHOWN = { opacity: 1, scale: 1 } as const;
const DEFAULT = {
    brand: { label: "Workspace Studio", href: "/" },
    status: "Open for new collaborations",
    headline: "Good things start with a conversation.",
    cta: { label: "hello@example.com", href: "mailto:hello@example.com" },
    links: [{ label: "Selected work", href: "/work" }, { label: "The studio", href: "/about" }, { label: "Our process", href: "/process" }],
    image: { src: "/assets/artemis/c900f3f4b9ce7c6d88ee.webp", alt: "A painted view of coastal cliffs and a quiet blue inlet" },
    location: "By the coast. Working everywhere.",
    tagline: "A small studio with a wider outlook.",
    legal: "\u00A9 2026 Workspace Studio",
    legalLinks: [{ label: "Privacy", href: "/privacy" }, { label: "Terms", href: "/terms" }],
    social: [{ label: "Instagram", href: "https://instagram.com" }, { label: "GitHub", href: "https://github.com" }, { label: "Email", href: "mailto:hello@example.com" }],
} satisfies ArtemisFooterContent;
/** The layout's own icons in order, for social links that come without one. */
const SOCIAL_ICONS = [
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="art:size-4">
      <rect x="3" y="3" width="18" height="18" rx="5"/>
      <circle cx="12" cy="12" r="4"/>
      <circle cx="17.5" cy="6.5" r="0.75" fill="currentColor" stroke="none"/>
    </svg>,
    <svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor" className="art:size-4">
      <path d="M12 1a11 11 0 0 0-3.48 21.44c.55.1.75-.24.75-.53v-1.87c-3.06.67-3.71-1.47-3.71-1.47-.5-1.28-1.22-1.62-1.22-1.62-1-.68.07-.67.07-.67 1.11.08 1.69 1.14 1.69 1.14.98 1.69 2.58 1.2 3.21.92.1-.71.39-1.2.7-1.48-2.44-.28-5.01-1.22-5.01-5.43 0-1.2.43-2.18 1.13-2.95-.11-.28-.49-1.4.11-2.9 0 0 .92-.3 3.02 1.12a10.4 10.4 0 0 1 5.5 0c2.1-1.42 3.02-1.12 3.02-1.12.6 1.5.22 2.62.11 2.9.7.77 1.13 1.75 1.13 2.95 0 4.22-2.58 5.15-5.03 5.42.4.35.75 1.03.75 2.08v3.08c0 .3.2.64.76.53A11 11 0 0 0 12 1z"/>
    </svg>,
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-mail art:size-4" aria-hidden="true">
      <path d="m22 7-8.991 5.727a2 2 0 0 1-2.009 0L2 7"/>
      <rect x="2" y="4" width="20" height="16" rx="2"/>
    </svg>,
];
/** Links to other sites open in a new tab. */
const newTab = (href: string) => (/^https?:/.test(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsStudio({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const links = content?.links ?? content?.columns?.flatMap((column) => column.links) ?? copy.links;
    const social: ArtemisFooterSocialLink[] = copy.social;
    return (<MotionConfig reducedMotion="user">
      <footer className="art:w-full art:bg-background art:px-6 art:py-8 art:text-foreground art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-12">
        <div className="art:mx-auto art:max-w-6xl">
          <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-4">
            <a href={copy.brand.href} {...newTab(copy.brand.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-2 art:rounded-full art:text-xl art:font-medium art:tracking-tight art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring">
              <span aria-hidden="true">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-asterisk art:size-7" aria-hidden="true">
                  <path d="M12 6v12"/>
                  <path d="M17.196 9 6.804 15"/>
                  <path d="m6.804 9 10.392 6"/>
                </svg>
              </span>
              {copy.brand.label}
            </a>
            <p className="art:inline-flex art:items-center art:gap-2 art:rounded-full art:border art:border-border art:px-3 art:py-2 art:text-xs art:text-muted-foreground">
              <span aria-hidden="true" className="art:size-1.5 art:rounded-full art:bg-foreground"/>
              {copy.status}
            </p>
          </div>
          <div className="art:grid art:gap-10 art:py-10 art:@min-[768px]/artemis:grid-cols-[1.6fr_1fr] art:@min-[768px]/artemis:items-end art:@min-[768px]/artemis:gap-16 art:@min-[640px]/artemis:py-12">
            <motion.div className="art:min-w-0" initial={TEXT_HIDDEN} whileInView={TEXT_SHOWN} viewport={{ once: true }} transition={{ duration: 0.5, ease: ARTEMIS_EASE_OUT }}>
              <p className="art:mb-4 art:text-sm art:text-muted-foreground">
                {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
              </p>
              <a href={copy.cta.href} {...newTab(copy.cta.href)} className="art:inline-flex art:max-w-full art:items-center art:gap-3 art:rounded-lg art:text-3xl art:font-medium art:tracking-tight art:underline art:decoration-border art:underline-offset-8 art:transition-colors art:hover:decoration-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-8 art:focus-visible:outline-ring art:@min-[640px]/artemis:text-4xl">
                <span className="art:min-w-0 art:break-all">
                  {copy.cta.label}
                </span>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-7 art:shrink-0" aria-hidden="true">
                  <path d="M7 7h10v10"/>
                  <path d="M7 17 17 7"/>
                </svg>
              </a>
              <nav aria-label="Studio" className="art:mt-8 art:flex art:flex-wrap art:gap-x-6 art:gap-y-1">
                {links.map((link, index) => <a key={index} href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:rounded-full art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:text-sm">
                  {link.label}
                </a>)}
              </nav>
            </motion.div>
            <div className="art:max-w-sm art:@min-[768px]/artemis:justify-self-end">
              <div className="art:overflow-hidden art:rounded-2xl">
                <motion.div initial={IMAGE_HIDDEN} whileInView={IMAGE_SHOWN} viewport={{ once: true }} transition={{ duration: 0.7, ease: ARTEMIS_EASE_OUT }}>
                  <img src={copy.image.src} alt={copy.image.alt} loading="lazy" className="art:aspect-[2/1] art:w-full art:object-cover art:dark:brightness-75"/>
                </motion.div>
              </div>
              <p className="art:mt-3 art:flex art:items-center art:gap-2 art:text-xs">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-map-pin art:size-3.5 art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                  <path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/>
                  <circle cx="12" cy="10" r="3"/>
                </svg>
                {copy.location}
              </p>
              <p className="art:mt-1 art:text-xs art:leading-5 art:text-muted-foreground">
                {copy.tagline}
              </p>
            </div>
          </div>
          <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-x-8 art:gap-y-4 art:border-t art:border-border art:pt-5">
            <div className="art:flex art:flex-wrap art:items-center art:gap-x-5 art:gap-y-1 art:text-xs art:text-muted-foreground">
              <p>
                {copy.legal}
              </p>
              <nav aria-label="Legal" className="art:flex art:gap-5">
                {copy.legalLinks.map((link, index) => <a key={index} href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:rounded-full art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:text-xs">
                  {link.label}
                </a>)}
              </nav>
            </div>
            <nav aria-label="Social links" className="art:flex art:gap-2">
              {social.map((link, index) => {
                const Icon = link.icon;
                return <a key={index} href={link.href} {...newTab(link.href)} aria-label={link.label} title={link.label} className="art:grid art:size-10 art:place-items-center art:rounded-full art:border art:border-border art:text-muted-foreground art:transition-colors art:hover:bg-muted art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-2 art:focus-visible:outline-ring">
                  <span aria-hidden="true">
                    {Icon ? <Icon className="art:size-4"/> : SOCIAL_ICONS[index % SOCIAL_ICONS.length]}
                  </span>
                </a>;
              })}
            </nav>
          </div>
        </div>
      </footer>
    </MotionConfig>);
}
